import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { TelemetryPoint, StagedLap } from '../types';
import { generateSeriesColors } from '../utils/teamColors';

// --- RESPONSIVE WRAPPER (Reused Pattern) ---
const ResponsiveApexChart: React.FC<{
    options: ApexOptions;
    series: ApexOptions['series'];
    type: "line" | "area" | "bar";
    className?: string;
}> = ({ options, series, type, className }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const [shouldRender, setShouldRender] = useState(false);

    useLayoutEffect(() => {
        if (!containerRef.current) return;
        const resizeObserver = new ResizeObserver((entries) => {
            if (!Array.isArray(entries) || !entries.length) return;
            const entry = entries[0];
            const { width, height } = entry.contentRect;
            if (width > 0 && height > 0) {
                requestAnimationFrame(() => setShouldRender(true));
            }
        });
        resizeObserver.observe(containerRef.current);
        return () => resizeObserver.disconnect();
    }, []);

    return (
        <div ref={containerRef} className={`w-full h-full relative min-h-[50px] ${className || ''}`}>
            {shouldRender ? (
                <ReactApexChart options={options} series={series} type={type} height="100%" width="100%" />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center opacity-30">
                     <div className="w-6 h-6 border-2 border-f1-red border-t-transparent rounded-full animate-spin"></div>
                </div>
            )}
        </div>
    );
};

interface TelemetryDeltaChartProps {
  data: TelemetryPoint[]; // Contains 'distance' and 'speed_ID'
  stagedLaps: StagedLap[];
}

const TelemetryDeltaChart: React.FC<TelemetryDeltaChartProps> = ({
  data,
  stagedLaps,
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [hiddenIndices, setHiddenIndices] = useState<Set<number>>(new Set());

  // --- DELTA CALCULATION LOGIC ---
  const { series, chartColors, allColors, referenceDriverName } = useMemo(() => {
      if (!data || data.length < 2 || stagedLaps.length === 0) {
          return { series: [], chartColors: [], allColors: [], referenceDriverName: '' };
      }

      const baseColors = generateSeriesColors(stagedLaps.map(s => ({ team_name: s.driver.team_name })));

      // Reference: FASTEST lap
      const refLap = [...stagedLaps].sort((a, b) => a.lap.lap_duration - b.lap.lap_duration)[0];
      const refTraceId = `${refLap.driver.name_acronym}_L${refLap.lap.lap_number}`;
      const referenceDriverName = refLap.driver.name_acronym;

      // ==========================================
      // TIME-BASED DELTA CALCULATION (CORRECT)
      // ==========================================

      // STEP 1: For each driver, build a TIME -> DISTANCE mapping
      // This is the INVERSE of what we were doing before
      const timeDistanceMaps = new Map<string, { time: number; distance: number }[]>();

      stagedLaps.forEach((sl) => {
          const id = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
          const speedKey = `speed_${id}`;

          const points: { time: number; distance: number }[] = [];
          let cumulativeTime = 0;
          let cumulativeDistance = 0;
          let prevDist = (data[0] as any).distance || 0;

          // Pre-filter speeds with EMA
          let emaSpeed = 0;
          const alpha = 0.25;

          for (let i = 0; i < data.length; i++) {
              const row = data[i] as any;
              const rawSpeed = (row[speedKey] as number);

              // Skip if no speed data for this driver (e.g. alignment gaps)
              if (rawSpeed === null || rawSpeed === undefined) continue;

              emaSpeed = i === 0 ? rawSpeed : alpha * rawSpeed + (1 - alpha) * emaSpeed;

              const currentDist = row.distance || 0;
              const deltaDist = i === 0 ? 0 : Math.abs(currentDist - prevDist);

              if (deltaDist > 0 && deltaDist < 50) {
                  const speedMs = Math.max(emaSpeed / 3.6, 2.0);
                  const deltaTime = deltaDist / speedMs;
                  cumulativeTime += Math.min(deltaTime, 1.5);
                  cumulativeDistance += deltaDist;

                  points.push({ time: cumulativeTime, distance: cumulativeDistance });
              }

              prevDist = currentDist;
          }

          timeDistanceMaps.set(id, points);
      });

      // STEP 2: Resample all drivers on a COMMON TIME GRID
      const refPoints = timeDistanceMaps.get(refTraceId);
      if (!refPoints || refPoints.length === 0) {
          return { series: [], chartColors: [], allColors: baseColors, referenceDriverName };
      }

      const maxTime = Math.max(...Array.from(timeDistanceMaps.values()).map(pts => pts[pts.length - 1]?.time || 0));
      const timeStep = 0.1; // 100ms resolution
      const numSteps = Math.floor(maxTime / timeStep);

      // Helper: Linear interpolation to find distance at given time
      const getDistanceAtTime = (points: { time: number; distance: number }[], targetTime: number): number => {
          if (points.length === 0) return 0;
          if (targetTime <= points[0].time) return points[0].distance;
          if (targetTime >= points[points.length - 1].time) return points[points.length - 1].distance;

          // Binary search for performance
          let low = 0, high = points.length - 1;
          while (low < high) {
              const mid = Math.floor((low + high) / 2);
              if (points[mid].time < targetTime) {
                  low = mid + 1;
              } else {
                  high = mid;
              }
          }

          const idx = low;
          if (idx === 0) return points[0].distance;

          const p1 = points[idx - 1];
          const p2 = points[idx];

          const ratio = (targetTime - p1.time) / (p2.time - p1.time);
          return p1.distance + (p2.distance - p1.distance) * ratio;
      };

      // STEP 3: Calculate TIME DELTA at each time point
      const deltaSeriesData: number[][][] = stagedLaps.map(() => []);

      let dataIdx = 0; // Cursor for efficient data lookup

      for (let step = 0; step <= numSteps; step++) {
          const currentTime = step * timeStep;

          const refDistance = getDistanceAtTime(refPoints, currentTime);

          // Efficiently find reference speed from original data
          while (dataIdx < data.length - 1 && (data[dataIdx+1] as any).distance < refDistance) {
              dataIdx++;
          }
          let closestDataPoint = data[dataIdx];
          // Check if next point is closer
          if (dataIdx < data.length - 1) {
             const d1 = Math.abs((data[dataIdx] as any).distance - refDistance);
             const d2 = Math.abs((data[dataIdx+1] as any).distance - refDistance);
             if (d2 < d1) closestDataPoint = data[dataIdx+1];
          }

          const refSpeedKey = `speed_${refTraceId}`;
          const refSpeedKph = (closestDataPoint as any)[refSpeedKey] || 50;
          const refSpeedMs = Math.max(refSpeedKph / 3.6, 5.0); // Clamp min speed

          stagedLaps.forEach((sl, idx) => {
              const id = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
              const points = timeDistanceMaps.get(id);
              if (!points) return;

              const myDistance = getDistanceAtTime(points, currentTime);

              // Delta = Distance Gap / Reference Speed
              // At time T, if I am behind (myDistance < refDistance), distanceGap is negative.
              // If I am behind, time delta should be positive (I am +0.2s slower).
              // Therefore: Time Delta = (RefDistance - MyDistance) / Speed
              // OR: Time Delta = -(MyDistance - RefDistance) / Speed
              const distanceGap = myDistance - refDistance;

              const timeDelta = -distanceGap / refSpeedMs;

              // We plot against RefDistance to show where on the track the time was lost
              deltaSeriesData[idx].push([refDistance, timeDelta]);
          });
      }

      // STEP 4: Light smoothing
      const smoothed = deltaSeriesData.map(series => {
          if (series.length < 5) return series;
          const result = [];
          for (let i = 0; i < series.length; i++) {
              const start = Math.max(0, i - 2);
              const end = Math.min(series.length, i + 3);
              let sum = 0;
              for (let j = start; j < end; j++) sum += series[j][1];
              result.push([series[i][0], sum / (end - start)]);
          }
          return result;
      });

      // Build final series
      const activeSeries: any[] = [];
      const activeColors: string[] = [];

      stagedLaps.forEach((sl, idx) => {
          if (hiddenIndices.has(idx)) return;

          activeSeries.push({
              name: `${sl.driver.name_acronym} (L${sl.lap.lap_number})`,
              data: smoothed[idx]
          });
          activeColors.push(baseColors[idx]);
      });

      return { series: activeSeries, chartColors: activeColors, allColors: baseColors, referenceDriverName };

  }, [data, stagedLaps, hiddenIndices]);

  // --- CHART OPTIONS ---
  const options: ApexOptions = useMemo(() => ({
      chart: {
          type: 'line',
          animations: { enabled: false },
          background: 'transparent',
          fontFamily: 'Inter, sans-serif',
          toolbar: { show: isExpanded },
          zoom: { enabled: isExpanded, type: 'x', autoScaleYaxis: true },
      },
      theme: { mode: 'dark' },
      colors: chartColors,
      stroke: {
          curve: 'monotoneCubic',
          width: 2,
      },
      grid: {
          borderColor: '#334155',
          strokeDashArray: 3,
          xaxis: { lines: { show: false } },
          yaxis: { lines: { show: true } },
          padding: { top: 10, right: 10, bottom: 10, left: 10 }
      },
      xaxis: {
          type: 'numeric',
          labels: {
              style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
              formatter: (val: string) => `${Math.round(Number(val))}m`
          },
          tooltip: { enabled: isExpanded }
      },
      yaxis: {
          title: { 
              text: 'Delta (s)', 
              style: { color: '#64748b', fontSize: '10px', fontFamily: 'Inter' } 
          },
          labels: {
              style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
              formatter: (val) => `${val > 0 ? '+' : ''}${val.toFixed(3)}s`,
          },
      },
      annotations: {
          yaxis: [{
              y: 0,
              borderColor: '#ffffff',
              strokeDashArray: 0,
              opacity: 0.3,
              borderWidth: 1,
              label: {
                  text: 'Reference',
                  style: { color: '#fff', background: '#333' }
              }
          }]
      },
      legend: { show: false },
      tooltip: {
          theme: 'dark',
          style: { fontSize: '12px', fontFamily: 'JetBrains Mono, monospace' },
          x: { formatter: (val) => `${Math.round(Number(val))}m` },
          y: { formatter: (val) => `${val > 0 ? '+' : ''}${val.toFixed(3)}s` }
      },
      markers: { size: 0, hover: { size: 5, strokeColors: '#fff', strokeWidth: 0 } }
  }), [chartColors, isExpanded]);

  const toggleVisibility = (index: number) => {
      const next = new Set(hiddenIndices);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      setHiddenIndices(next);
  };

  if (!data || data.length === 0 || stagedLaps.length === 0) return null;

  return (
    <>
      <div className="relative w-full h-[320px] bg-f1-surface border border-white/5 rounded-lg p-4 flex flex-col mb-6 hover:border-white/10 transition-colors shadow-lg group/chart">

        {/* HEADER */}
        <div className="flex justify-between items-center mb-2 shrink-0 h-8">
            <div className="flex items-center gap-2">
                 <button 
                    onClick={() => setIsExpanded(true)}
                    className="p-1.5 rounded hover:bg-white/10 text-f1-muted hover:text-white transition-colors active:scale-95"
                    title="Expand Chart"
                >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    </svg>
                </button>
                <div className="flex flex-col">
                    <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted px-1">
                        Time Delta
                    </h3>
                    <span className="text-[9px] text-f1-muted/70 px-1 font-mono">
                        Ref: {referenceDriverName}
                    </span>
                </div>
            </div>

            <div className="flex flex-wrap gap-2">
                {stagedLaps.map((sl, index) => {
                    const isHidden = hiddenIndices.has(index);
                    const color = allColors[index];
                    return (
                        <button 
                            key={sl.id} 
                            onClick={(e) => { e.stopPropagation(); toggleVisibility(index); }}
                            className={`flex items-center gap-2 px-2 py-1 rounded border border-transparent text-[10px] font-medium transition-all active:scale-95 duration-100 ${isHidden ? 'opacity-40 grayscale bg-transparent line-through text-f1-muted' : 'bg-white/5 hover:bg-white/10 text-f1-text'}`}
                        >
                            <span className="w-2 h-2 rounded-full" style={{ backgroundColor: color }}></span>
                            <span className="uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</span>
                        </button>
                    );
                })}
            </div>
        </div>

        {/* CHART CONTAINER */}
        <div className="flex-1 w-full min-h-0 relative">
            <ResponsiveApexChart options={options} series={series} type="line" />
        </div>
      </div>

      {/* FULLSCREEN MODAL */}
      <AnimatePresence>
        {isExpanded && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                <motion.div 
                    initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                    onClick={() => setIsExpanded(false)}
                    className="absolute inset-0 bg-black/90 backdrop-blur-sm"
                />
                <motion.div 
                    initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }}
                    className="relative w-full max-w-7xl h-[85vh] bg-[#0F1014] border border-f1-border rounded-xl p-6 shadow-2xl flex flex-col"
                >
                     <div className="flex justify-between items-center mb-6 shrink-0">
                        <div>
                             <h3 className="text-lg font-bold uppercase tracking-widest text-white">
                                Time Delta Analysis <span className="text-f1-muted text-sm ml-2">(Ref: {referenceDriverName})</span>
                            </h3>
                        </div>
                        <button 
                            onClick={() => setIsExpanded(false)}
                            className="p-3 bg-white/5 hover:bg-white/10 hover:text-white text-f1-muted rounded-full transition-all active:scale-95"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>
                    <div className="flex-1 w-full min-h-0 bg-[#0B0B0F] rounded-lg p-2 border border-white/5">
                         <ResponsiveApexChart options={options} series={series} type="line" />
                    </div>
                </motion.div>
            </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default React.memo(TelemetryDeltaChart);
